// blur.c
unsigned char* blur_image(const unsigned char* in, size_t n, int radius, size_t* out_len) {
  if (!in || n == 0 || radius <= 0) return NULL;
  unsigned char* out = malloc(n);
  if (!out) return NULL;
  for (size_t i = 0; i < n; ++i) out[i] = in[i];
  *out_len = n;
  return out;
}
